svg.script:
// 
var presets = {"satellite":{"layers":["board-image"],"style":"photo"},"analysis":{"layers":["board-image","components","traces","bom-panel"],"style":"photo"},"schematic":{"layers":["components","traces","net-labels","grid-ref","bom-panel"],"style":"schematic"},"xray":{"layers":["board-image","components","traces","zones","security","power-rails","net-labels"],"style":"xray"},"attack":{"layers":["board-image","security","traces"],"style":"photo"},"recon":{"layers":["board-image","security","traces","power-rails","net-labels"],"style":"xray"},"power":{"layers":["board-image","power-rails","zones","components"],"style":"photo"},"zones":{"layers":["board-image","zones","components"],"style":"photo"},"debug":{"layers":["board-image","security","net-labels"],"style":"photo"},"all":{"layers":["board-image","components","traces","zones","security","power-rails","bom-panel","net-labels","grid-ref"],"style":"photo"},};
var allLayers = ["board-image","components","traces","zones","security","power-rails","bom-panel","net-labels","grid-ref"];
var allStyles = ["photo","schematic","xray"];

function toggleLayer(id) {
  var g = document.getElementById("layer-" + id);
  if (!g) return;
  var vis = g.getAttribute("visibility");
  var show = vis === "hidden";
  g.setAttribute("visibility", show ? "visible" : "hidden");
  var chk = document.getElementById("chk-" + id);
  var tick = document.getElementById("tick-" + id);
  if (chk) chk.setAttribute("fill", show ? "#22d3ee" : "#1e293b");
  if (tick) tick.style.display = show ? "" : "none";
}

function setStyle(mode) {
  var root = document.querySelector("svg");
  allStyles.forEach(function(s) {
    root.classList.remove("style-" + s);
  });
  root.classList.add("style-" + mode);
}

function setPreset(name) {
  var p = presets[name];
  if (!p) return;
  var layers = p.layers || [];
  allLayers.forEach(function(id) {
    var g = document.getElementById("layer-" + id);
    if (!g) return;
    var show = layers.indexOf(id) >= 0;
    g.setAttribute("visibility", show ? "visible" : "hidden");
    var chk = document.getElementById("chk-" + id);
    var tick = document.getElementById("tick-" + id);
    if (chk) chk.setAttribute("fill", show ? "#22d3ee" : "#1e293b");
    if (tick) tick.style.display = show ? "" : "none";
  });
  setStyle(p.style || "photo");
}
//
